SET @catalog_version = 'catalog-expansion-2025-v1';
SET @catalog_limit = GREATEST(0, 500 - (SELECT COUNT(*) FROM products WHERE status = 'ON_SALE'));

INSERT INTO products (sku, name, category, brand, model, summary, image_url, price, stock,
                      status, source_url, price_note, data_version)
SELECT candidate.sku, candidate.name, candidate.category, candidate.brand, candidate.model,
       candidate.summary, candidate.image_url, candidate.price, candidate.stock, 'ON_SALE',
       JSON_UNQUOTE(JSON_EXTRACT(candidate.parameters, '$[0].sourceUrl')),
       CASE WHEN candidate.stock = 0 THEN 'CNY 演示标价，库存待确认'
            ELSE 'CNY 演示价格与库存，非实时市场报价' END,
       @catalog_version
FROM (
    SELECT imported.*, ROW_NUMBER() OVER (ORDER BY imported.position) AS candidate_number
    FROM JSON_TABLE(@catalog_rows, '$[*]' COLUMNS (
        position FOR ORDINALITY,
        sku VARCHAR(80) PATH '$[0]',
        name VARCHAR(180) PATH '$[1]',
        category VARCHAR(16) PATH '$[2]',
        brand VARCHAR(60) PATH '$[3]',
        model VARCHAR(100) PATH '$[4]',
        summary VARCHAR(240) PATH '$[5]',
        image_url VARCHAR(500) PATH '$[6]',
        price DECIMAL(12,2) PATH '$[7]',
        stock INT PATH '$[8]',
        parameters JSON PATH '$[10]'
    )) imported
    WHERE NOT EXISTS (
        SELECT 1 FROM products existing
        WHERE existing.sku = imported.sku
           OR (existing.category = imported.category
               AND (existing.name = imported.name OR existing.model = imported.model))
    )
) candidate
WHERE candidate.candidate_number <= @catalog_limit
ORDER BY candidate.candidate_number;

INSERT INTO product_specifications (product_id, description, parameters, data_version, verified_on)
SELECT p.id, imported.description, imported.parameters, @catalog_version, '2026-11-18'
FROM JSON_TABLE(@catalog_rows, '$[*]' COLUMNS (
    sku VARCHAR(80) PATH '$[0]',
    description TEXT PATH '$[9]',
    parameters JSON PATH '$[10]'
)) imported
JOIN products p ON p.sku = imported.sku AND p.data_version = @catalog_version
WHERE NOT EXISTS (SELECT 1 FROM product_specifications s WHERE s.product_id = p.id);

COMMIT;
